import re
from decimal import Decimal

_PATTERN = re.compile(r"[+-]?[0-9]+(?:\.[0-9]+)?", re.ASCII)
MAX_CENTS = 100000000  # 1000000.00


def _cents(value):
    """Validate value and return its exact integer number of cents."""
    if isinstance(value, bool):
        raise ValueError("invalid amount")
    if isinstance(value, str):
        if not _PATTERN.fullmatch(value):
            raise ValueError("invalid amount")
        value = Decimal(value)  # construction is exact regardless of context
    elif isinstance(value, int):
        value = Decimal(value)
    elif not isinstance(value, Decimal):
        raise ValueError("invalid amount")
    if not value.is_finite():
        raise ValueError("invalid amount")
    sign, digits, exp = value.as_tuple()
    coef = int("".join(map(str, digits)))
    if sign or coef == 0:
        raise ValueError("amount must be positive")
    # Bound magnitude before any big arithmetic.
    if exp + len(digits) > 9:
        raise ValueError("amount too large")
    if exp >= -2:
        cents = coef * 10 ** (exp + 2)
    else:
        drop = -2 - exp
        if drop > len(digits):
            raise ValueError("amount not representable in cents")
        cents, rem = divmod(coef, 10 ** drop)
        if rem:
            raise ValueError("amount not representable in cents")
    if cents == 0:
        raise ValueError("amount must be positive")
    if cents > MAX_CENTS:
        raise ValueError("amount too large")
    return cents


def _from_cents(cents):
    return Decimal((0, tuple(int(c) for c in str(cents)), -2))


def parse_amount(value):
    return _from_cents(_cents(value))


def format_amount(value):
    return format(value, ".2f")
